records.patch:
--- app/wwudp/cordcon.cpp
+++ app/wwudp/cordcon.cpp
@@ -2087,6 +2087,13 @@
 	Queued_++;
 }

+static inline void Cord_Append_Ack_Record(unsigned char *list, int &pos, std::vector<CordChannelClass *> &active, int &index, const unsigned int &seq) // NAME 1: kind-0 ACK record encoding at 0x8554AB-0x85551A
+{
+	list[pos++] = 0;
+	pos += Cord_Put_Small(list + pos, (unsigned short)active[index]->Index);
+	pos += Cord_Put_Seq(list + pos, seq);
+}
+
 // 0x8551F0: the datagram header and the ack list (at most 8 acks and 32 resend requests).
 bool CordCon::buildHeader(unsigned char *out, int *len, unsigned short *counter)
 {
@@ -2099,7 +2106,7 @@
 	int entries = 0;
 	int last = 0;
 	unsigned int seq = 0;
-	*(unsigned short *)(out + 1) = htons((unsigned short)Session_);
+	unsigned short session = (unsigned short)Session_; session = htons(session); *(unsigned short *)(out + 1) = session;
 	*counter = (unsigned short)PacketsOut_;
 	*(unsigned short *)(out + 3) = htons(*counter);
 	*(unsigned long *)(out + 5) = htonl(0);
@@ -2145,9 +2152,9 @@
 		}
 		if (acks < 8 && Active_[i]->ToAck.removeHead(seq)) {
 			AcksPending_--;
-			list[pos++] = 0;
-			pos += Cord_Put_Small(list + pos, (unsigned short)Active_[i]->Index);
-			pos += Cord_Put_Seq(list + pos, seq);
+			Cord_Append_Ack_Record(list, pos, Active_, i, seq);
+
+
 			acks++;
 			entries++;
 		}

--- app/wwudp/cordcon.cpp
+++ app/wwudp/cordcon.cpp
@@ -2099,7 +2099,7 @@
 	int entries = 0;
 	int last = 0;
 	unsigned int seq = 0;
-	*(unsigned short *)(out + 1) = htons((unsigned short)Session_);
+	unsigned short session = (unsigned short)Session_; session = htons(session); *(unsigned short *)(out + 1) = session;
 	*counter = (unsigned short)PacketsOut_;
 	*(unsigned short *)(out + 3) = htons(*counter);
 	*(unsigned long *)(out + 5) = htonl(0);

